const GIFT_THRESHOLDS = Object.keys(GIFT_SVGS).map(Number).sort((a, b) => b - a);

export function getKickRoleBadge(badge) {
  const candidates = typeof badge === 'string' ? [badge] : [badge?.type, badge?.name, badge?.text, badge?.label];
  for (const value of candidates) {
    if (typeof value !== 'string') continue;
    let role = value.trim().toLowerCase();
    if (role === 'sub gifter' || role === 'sub_gifter') {
      const count = Number(badge?.count) || 1;
      const tier = GIFT_THRESHOLDS.find(value => count >= value) || 1;
      return { type: 'svg', html: GIFT_SVGS[tier] };
    }
    if (role === 'verified channel') role = 'verified';
    if (role === 'mod') role = 'moderator';
    if (role === 'host') role = 'broadcaster';
    if (Object.prototype.hasOwnProperty.call(ROLE_SVGS, role)) {
      return { type: 'svg', html: ROLE_SVGS[role] };
    }
  }
  return null;
}
